import 'dart:collection';

List<Map<String, dynamic>> analyzeTransactions(List<Transaction> transactions) {
  // Group transactions by coin and calculate avg profit/loss
  final groupedTransactions = transactions.groupBy((t) => t.coinName);
  final avgProfits = <String, double>{};
  final avgLosses = <String, double>{};
  for (var (coin, coinTransactions) in groupedTransactions.entries) {
    double totalProfit = 0;
    double totalLoss = 0;
    for (var transaction in coinTransactions) {
      totalProfit += transaction.profit;
      totalLoss += transaction.loss; // Assuming loss is negative profit
    }
    avgProfits[coin] = totalProfit / coinTransactions.length;
    avgLosses[coin] = totalLoss / coinTransactions.length;
  }

  // Extract top 3 with highest avg profit and loss
  final topProfits = avgProfits.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value))
    ..sublist(0, 3)
    .map((entry) => {'coin': entry.key, 'avgProfit': entry.value})
    .toList();

  final topLosses = avgLosses.entries.toList()
    ..sort((a, b) => a.value.compareTo(b.value)) // Sort by ascending loss for "highest loss"
    ..sublist(0, 3)
    .map((entry) => {'coin': entry.key, 'avgLoss': entry.value})
    .toList();

  return [topProfits, topLosses];
}

