```cpp
#include <iostream>
#include <vector>
#include <jsoncpp/json/json.h> // Assuming you use JsonCpp for JSON handling

void bubbleSort(std::vector<int>& arr) {
    int n = arr.size();
    bool swapped;
    do {
        swapped = false;
        for (int i = 0; i < n - 1; ++i) {
            if (arr[i] > arr[i + 1]) {
                std::swap(arr[i], arr[i + 1]);
                swapped = true;
            }
        }
        n--; // One less comparison needed in each iteration
    } while (swapped);
}

int main() {
    // **JSON Handling (Example with JsonCpp)**
    Json::Value root;
    root["array"] = Json::Value(Json::arrayValue);
    root["array"].append(5);
    root["array"].append(2);
    root["array"].append(9);
    root["array"].append(1);
    root["array"].append(5);
    root["array"].append(6);

    Json::StyledWriter writer;
    std::string jsonInput = writer.write(root);  // Serialize to JSON string

    // Parse JSON into a vector for sorting
    Json::Reader reader;
    Json::Value parsedJson;
    reader.parse(jsonInput, parsedJson);
    std::vector<int> data(parsedJson["array"].begin(), parsedJson["array"].end());

    bubbleSort(data);

    // **Output (Back to JSON Format)**
    Json::Value sortedRoot;
    sortedRoot["sorted_array"] = Json::Value(Json::arrayValue);
    for (int num : data) {
        sortedRoot["sorted_array"].append(num);
    }
    std::string outputJson = writer.write(sortedRoot);
    std::cout << outputJson << std::endl;

    return 0;
}
```

