public class PurchaseCalculator
{
    public double CalculateTotalCost(double carPrice, double clothesPrice, double bookPrice)
    {
        // 1. Constraint Check:
        double combinedClothingBookPrice = clothesPrice + bookPrice;
        if (carPrice < 2 * combinedClothingBookPrice)
        {
            // 2. Adjust Car Price (if needed):
            carPrice = Math.Ceiling(2 * combinedClothingBookPrice); // Ensure car price is at least double
            Console.WriteLine("Car price adjusted to meet constraint: $" + carPrice); 
        }

        // 3. Calculate Total Cost:
        double totalPrice = carPrice + clothesPrice + bookPrice;
        return totalPrice;
    }
}

// Usage with provided initial prices:
