}

func generateMeaningfulStatement(profile: UserProfile) -> String {
    // 1. Extract Dominant Click & Sentiment:
    let mostClicked = profile.clickHistory.mostFrequent() //  Swift utility to find most frequent element
    let sentimentForMostClicked = profile.reviewSentiment[mostClicked] ?? 0 // Default to neutral if no review

    // 2. Identify Preferred Color Context:
    let preferredColor = profile.colorPrefs.sorted { $0.value > $1.value }.first?.key ?? "neutral" // Highest scored color

    // 3. Construct Statement (Prioritize Clarity over Length)
    var statement = "Based on interactions, the user shows strong interest in \(mostClicked)"
    if sentimentForMostClicked > 0 { statement += " with positive reviews." } else { statement += " which may require further consideration." }
    if preferredColor != "neutral" { statement += " particularly favoring \(preferredColor)." }

    return statement
}

