using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json; // Or your preferred JSON serialization library

public class RestServiceWrapper<T> where T : class
{
    private readonly HttpClient _client;
    private readonly string _baseUrl;
    private string _authToken;

    public RestServiceWrapper(string baseUrl, string initialAuthToken = null)
    {
        _baseUrl = baseUrl;
        _authToken = initialAuthToken;
        _client = new HttpClient { BaseAddress = new Uri(_baseUrl) };
    }

    public void SetAuthToken(string token) => _authToken = token;

    protected async Task<HttpResponseMessage> MakeRequestAsync(HttpMethod method, string relativeUrl, object content = null)
    {
        var request = new HttpRequestMessage(method, relativeUrl);
        if (!string.IsNullOrEmpty(_authToken))
            request.Headers.Add("Authorization", $"Bearer {_authToken}"); 

        if (content != null)
            request.Content = new StringContent(JsonConvert.SerializeObject(content), System.Text.Encoding.UTF8, "application/json");

        return await _client.SendAsync(request);
    }

    // Example Usage (Generic Methods - Adapt to your API specifics)
    public async Task<T> GetAsync(string relativeUrl) => 
        await HandleResponse<T>(await MakeRequestAsync(HttpMethod.Get, relativeUrl));

    public async Task<T> PostAsync(string relativeUrl, object data) => 
        await HandleResponse<T>(await MakeRequestAsync(HttpMethod.Post, relativeUrl, data));

    public async Task<HttpResponseMessage> DeleteAsync(string relativeUrl) => 
        await MakeRequestAsync(HttpMethod.Delete, relativeUrl);

    private async Task<T> HandleResponse<T>(HttpResponseMessage response) where T : class
    {
        if (!response.IsSuccessStatusCode)
            throw new Exception($"API Error: {response.ReasonPhrase} ({(int)response.StatusCode})");

        var content = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<T>(content); // Deserialize based on your API's response format
    }
}
