  dataRange.getValues().forEach(function(row, rowIdx) {
    const placeName = row[0]; // Assuming place name is in the first element of each row
    if (placeName) {
      const geocoder = new google.maps.Geocoder();
      geocoder.geocode({ address: placeName }, function(results, status) {
        if (status === google.maps.GeocoderStatus.OK) {
          const lat = results[0].geometry.location.lat();
          const lng = results[0].geometry.location.lng();
          sheet.getRange(rowIdx + 2, latColumn).setValue(lat);  // Set latitude (adjust row offset if needed)
          sheet.getRange(rowIdx + 2, lngColumn).setValue(lng);  // Set longitude (adjust row offset if needed)
        } else {
          Logger.log(`Geocoding failed for ${placeName}: ${status}`);
        }
      });
    }
  });
}
```

