  const [unit, setUnit] = useState('celsius'); // Default: Celsius

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value));
  };

  const handleUnitChange = (event) => {
    setUnit(event.target.value);
  };

  // Conversion functions (Celsius to other units)
  const celsiusToFahrenheit = (c) => (c * 9/5) + 32;
  const celsiusToKelvin = (c) => c + 273.15;

  let convertedTemp;
  switch (unit) {
    case 'fahrenheit':
      convertedTemp = (temperature - 32) * 5/9; // Convert back to Celsius for display
      break;
    case 'kelvin':
      convertedTemp = temperature - 273.15; // Convert back to Celsius for display
      break;
    default: // celsius
      convertedTemp = temperature;
  }

  return (
    <div>
      <input type="number" value={temperature} onChange={handleInputChange} />
      <select value={unit} onChange={handleUnitChange}>
        <option value="celsius">Celsius</option>
        <option value="fahrenheit">Fahrenheit</option>
        <option value="kelvin">Kelvin</option>
      </select>
      <p>Converted: {convertedTemp.toFixed(2)} {unit === 'celsius' ? '°C' : unit === 'fahrenheit' ? '°F' : 'K'}</p>
    </div>
  );
};

export default TemperatureConverter;
```

