package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
	"strings"

	"github.com/apache/avro-go/schema"
)

func structToAvroSchema(filePath string, structName string) (string, error) {
	// 1. Parse Go Source
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filePath, nil, parser.AllErrors)
	if err != nil {
		return "", fmt.Errorf("parsing Go file: %w", err)
	}

	// 2. Find Target Struct Definition
	for _, decl := range file.Decls {
		if structDecl, ok := decl.(*ast.TypeSpec); ok && structDecl.Name.Name == structName {
			structType := structDecl.Type.(*ast.StructType)
			return buildAvroSchema(structType), nil // Construct Avro schema from found struct
		}
	}
	return "", fmt.Errorf("struct '%s' not found in file '%s'", structName, filePath)
}

func buildAvroSchema(structType *ast.StructType) string {
	avroSchema := map[string]interface{}{}
	avroSchema["type"] = "record"
	avroSchema["name"] = structType.Name.Name

	fields := make([]map[string]interface{}, 0)
	for _, field := range structType.Fields.List {
		fieldSchema := map[string]interface{}{
			"name": field.Names[0].Name,
			"type":  dataTypeToAvro(field.Type),
		}
		fields = append(fields, fieldSchema)
	}
	avroSchema["fields"] = fields

	// JSON Marshal for Avro Schema String Format
	schemaJSON, err := json.MarshalIndent(avroSchema, "", "  ")
	if err != nil {
		log.Fatalf("Error marshaling Avro schema: %v", err)
	}
	return string(schemaJSON)
}

