**3.  Template Fetching (Component: `TemplateProvider`)**

   *   Create a `TemplateProvider.jsx` component (e.g., in `src/components`). This component will manage fetching and storing the template data:

     ```javascript
     import React, { useState, useEffect } from 'react';
     import axios from 'axios';

     const TemplateProvider = ({ children }) => {
       const [template, setTemplate] = useState(null);
       const [isLoading, setIsLoading] = useState(true);
       const [error, setError] = useState(null);

       useEffect(() => {
         const fetchTemplate = async () => {
           try {
             const response = await axios.get('http://localhost:8080/template');
             setTemplate(response.data);
           } catch (err) {
             setError(err);
           } finally {
             setIsLoading(false);
           }
         };
         fetchTemplate();
       }, []); // Empty dependency array ensures fetching happens only once on mount

       if (isLoading) return <div>Loading template...</div>;
       if (error) return <div>Error fetching template: {error.message}</div>;

       return (
         <React.StrictMode>
           {/* Wrap children with template data */}
           <ResponseContext.Provider value={template}>
             {children}
           </ResponseContext.Provider>
         </React.StrictMode>
       );
     };

     export default TemplateProvider;
     ```

