import React, { createContext, useState, useContext } from 'react';

// 1. Create a Context for Toast State
const ToastContext = createContext();

// 2. Provider Component to manage toasts
const ToastProvider = ({ children }) => {
  const [showToast, setShowToast] = useState(false);
  const [message, setMessage] = useState('');
  const [type, setType] = useState('success'); // Default type, can be 'success', 'error', etc.

  const showToastNotification = (msg, toastType = 'success') => {
    setMessage(msg);
    setType(toastType);
    setShowToast(true);
    // Automatically hide after a short delay (e.g., 3 seconds)
    setTimeout(() => setShowToast(false), 3000); 
  };

  return (
    <ToastContext.Provider value={{ showToast, message, type, showToastNotification }}>
      {children}
    </ToastContext.Provider>
  );
};

// 3. Consumer Component (simplified using useContext)
const ToastNotification = () => {
  const { showToast, message, type } = useContext(ToastContext);

  if (!showToast) return null; 

  return (
    <div className={`toast ${type}`}>
      {message}
    </div>
  );
};

// Usage Example:
const App = () => {
  return (
    <ToastProvider>
      {/* ... your app components ... */}
      <button onClick={() => { useContext(ToastContext).showToastNotification('Success! Data saved.', 'success'); }}>Trigger Toast</button>
      <ToastNotification /> 
    </ToastProvider>
  );
};

export default App;
```

**Explanation:**

1. **Context Creation:** We establish `ToastContext` to share toast data (visible state, message, and type) across the app.

2. **Provider (`ToastProvider`):**
   - Holds the state: `showToast`, `message`, `type`.
   - `showToastNotification` function:  Sets up and triggers a toast, automatically hiding it after a delay.
   - Wraps components within `<ToastContext.Provider>` to make the state accessible.

3. **Consumer (`ToastNotification`):**
   - Uses `useContext(ToastContext

