import React, { useState, useRef } from 'react';
import { Combobox, Input, Transition } from 'downshift';
import { searchEmails } from './emailService'; // Assuming your async function resides here

const EmailAutocomplete = () => {
  const [emails, setEmails] = useState<string[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleInputChange = async (inputValue: string) => {
    if (inputValue.length > 2) { // Trigger search after at least 3 characters
      const suggestions = await searchEmails(inputValue);
      setEmails(suggestions);
    } else {
      setEmails([]); // Clear suggestions on shorter inputs
    }
  };

  return (
    <Combobox
      itemToString={(email) => email} // Display full email as selected item
      onChange={(selectedItem) => {
        // Update input with selected email and clear suggestions
        inputRef.current?.value = selectedItem || ''; 
        setEmails([]); 
      }}
    >
      <div className="combobox-container">
        <Input
          ref={inputRef}
          onChange={handleInputChange}
          placeholder="Enter email address..."
          width="300px" // Adjust width as needed
        />
        <Transition show={emails.length > 0}>
          <ul className="dropdown-menu">
            {emails.map((email) => (
              <li key={email}>{email}</li>
            ))}
          </ul>
        </Transition>
      </div>
    </Combobox>
  );
};

export default EmailAutocomplete;
```

**Explanation and Key Points (Prioritizing Helpfulness):**

1. **Downshift Integration:**  We leverage `downshift`'s `Combobox` for seamless autocomplete functionality.
