        // Calculate expenses for each product type
        double headphoneExpenses = headphoneQuantity * headphonePrice;
        double microphoneExpenses = microphoneQuantity * microphonePrice;
        double speakerExpenses = speakerQuantity * speakerPrice;

        // Compute total expenses
