    if (mysql_query(conn, sqlQuery.c_str())) {
        cerr << "Error: SQL query failed during tragedy lookup" << endl;
        mysql_close(conn);
        return 1; // Indicate error
    }

    MYSQL_RES* result = mysql_store_result(conn);
    MYSQL_ROW row = mysql_fetch_row(result);
    if (row) {
        string retrievedName = row[0];
        string summary = row[1];
        cout << "Identified Tragedy: " << retrievedName << endl;
        cout << "Summary: " << summary << endl;
    } else {
        cout << "No matching tragedy found for '" << queryTragedy << "' in the database." << endl;
    }

    mysql_free_result(result);
    mysql_close(conn);
    return 0; 
}
