// utils/redis.js

const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = redis.createClient();
    this.client.on('error', (err) => console.error('Redis Client Error:', err)); 
  }

  isAlive() {
    return this.client.status === 'ready'; 
  }

  async get(key) {
    try {
      return await this.client.get(key);
    } catch (err) {
      console.error(`Error fetching from Redis (key: ${key}):`, err);
      return null; // Or handle more robustly based on your needs
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.SET(key, value, 'EX', duration);
      return true; 
    } catch (err) {
      console.error(`Error setting in Redis (key: ${key}):`, err);
      return false; // Indicate failure
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
      return true;
    } catch (err) {
      console.error(`Error deleting from Redis (key: ${key}):`, err);
      return false; // Indicate failure
    }
  }
}

// Export an instance
const redisClient = new RedisClient();
module.exports = redisClient;
```

